using System.Net.Http.Json;
using System.Text;
using var client = new HttpClient(new FixtureHandler()) { BaseAddress = new Uri("https://example.test/") };
var student = await client.GetFromJsonAsync<Student>("students/1");
Console.WriteLine(student?.Name ?? "(rỗng)");
record Student(string Name);
class FixtureHandler : HttpMessageHandler
{
    protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken token)
    {
        string json = "{\"name\":\"An\"}";
        return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK) {
            Content = new StringContent(json, Encoding.UTF8, "application/json")
        });
    }
}

